// Dropdown renders <sb-dropdown>: An actions menu with submenus, commands to
// post and a current choice.
//
// Children render inside the element. Its slots (give a child slot="<name>"
// for a named one):
//   - trigger: Content of the trigger button (text, an icon). The component
//     provides the button itself, with all the ARIA on it.
//   - item: Menu items as markup instead of items: <button slot="item"
//     value="x" disabled data-icon="🛰" data-description="…"
//     data-danger>Label</button>, <a slot="item" href="/x">Label</a> for a
//     link, or <hr slot="item"> for a divider. <div slot="item"
//     data-group>Move to</div> is a group heading: the items after it, up to
//     the next heading or divider, are its group (text only). A submenu is
//     data-children='[…]' (the same JSON as items). They are read as data;
//     items wins when it is not empty. Rich items: an element marked data-icon
//     inside the item (an inline <svg>, an <img>) is copied into the row's
//     icon place, and other elements in it (a lozenge) are copied into the row
//     in place of the text, which stays the row's accessible name; a radio
//     trigger shows the chosen item the same way. Copies keep their
//     attributes, so part="…" and an inline style reach them from the page.
//
// Events, to listen to with Attrs ("data-on:sb-close"):
//   - sb-select: A plain item was chosen; the whole menu closes. detail: {
//     name, value }: ready for a command. A submenu parent never reports a
//     value, an item of a radio group reports sb-change instead, and a link
//     reports nothing: the browser follows it.
//   - change: Radio group: the value changed.
//   - sb-change: Radio group: an item of the group was chosen. detail: { name,
//     value }, the value being the dotted path for a choice inside a submenu:
//     ready for a command.
//   - sb-open: The menu opened (the root; submenus are view state and stay
//     quiet).
//   - sb-close: The menu closed. detail: { reason }: item, escape, outside,
//     scroll, tab, trigger, server or api.
//
// Docs: https://starbase.zweiundeins.gmbh/components/dropdown
func Dropdown(p DropdownProps) templ.Component {
	return templ.ComponentFunc(func(ctx context.Context, w io.Writer) error {
		used(ctx, TagDropdown)
		e := newElement("sb-dropdown", p.ID, p.Class, p.Attrs)
		e.json("items", p.Items, p.Items == nil)
		e.str("label", p.Label)
		e.str("empty-label", p.EmptyLabel)
		e.enum("placement", string(p.Placement), "bottom-start", "bottom", "bottom-end", "top-start", "top", "top-end")
		e.enum("type", string(p.Type), "actions", "radio")
		e.strPtr("value", p.Value)
		e.bool("confirm", p.Confirm)
		e.bool("open", p.Open)
		e.bool("disabled", p.Disabled)
		e.str("name", p.Name)
		return e.render(ctx, w)
	})
}

